import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < k; i++) {
            base[in.nextInt()] = 1;
        }

        int[] result = {1};
        int exponent = n / 2;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = convolve(result, base, MOD);
            }
            base = convolve(base, base, MOD);
            exponent >>= 1;
        }

        long answer = 0;
        for (int val : result) {
            answer = (answer + (long)val * val) % MOD;
        }
        out.println(answer);
        out.close();
    }

    static int[] convolve(int[] x, int[] y, int mod) {
        int m = x.length, n = y.length;
        int size = 1;
        while (size < m + n - 1) size <<= 1;

        double[] xr = new double[size];
        double[] xi = new double[size];
        double[] yr = new double[size];
        double[] yi = new double[size];

        for (int i = 0; i < m; i++) {
            long v = ((long)x[i] % mod + mod) % mod;
            xr[i] = v & 0x7fff;
            xi[i] = v >>> 15;
        }
        for (int i = 0; i < n; i++) {
            long v = ((long)y[i] % mod + mod) % mod;
            yr[i] = v & 0x7fff;
            yi[i] = v >>> 15;
        }

        fft(xr, xi, false);
        fft(yr, yi, false);

        double[] resR = new double[size];
        double[] resI = new double[size];
        double[] tmpR = new double[size];
        double[] tmpI = new double[size];

        double scale = 0.25 / size;
        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (xr[i] + xr[j]) * 0.5;
            double a1i = (xi[i] - xi[j]) * 0.5;
            double a2r = (xi[i] + xi[j]) * 0.5;
            double a2i = (xr[j] - xr[i]) * 0.5;

            double b1r = (yr[i] + yr[j]) * 0.5;
            double b1i = (yi[i] - yi[j]) * 0.5;
            double b2r = (yi[i] + yi[j]) * 0.5;
            double b2i = (yr[j] - yr[i]) * 0.5;

            resR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            tmpR[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            tmpI[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(resR, resI, true);
        fft(tmpR, tmpI, true);

        int len = m + n - 1;
        int[] out = new int[len];
        for (int i = 0; i < len; i++) {
            long p1 = Math.round(resR[i]);
            long p2 = Math.round(tmpR[i]);
            long p3 = Math.round(resI[i]);
            out[i] = (int)((p1 + (p2 % mod << 15) + (p3 % mod << 30)) % mod);
        }
        return out;
    }

    static void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        int bits = 32 - Integer.numberOfLeadingZeros(n - 1);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> (32 - bits);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cos = new double[half];
            double[] sin = new double[half];
            double angle = 2 * Math.PI / len * (inv ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cos[i] = Math.cos(i * angle);
                sin[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double cr = cos[j], ci = sin[j];
                    double ur = re[i + j], ui = im[i + j];
                    double vr = re[i + j + half] * cr - im[i + j + half] * ci;
                    double vi = re[i + j + half] * ci + im[i + j + half] * cr;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + half] = ur - vr;
                    im[i + j + half] = ui - vi;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int p, len;

        public InputReader(InputStream in) { this.in = in; }

        private int next() {
            if (len == -1) throw new RuntimeException();
            if (p >= len) {
                p = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[p++] & 255;
        }

        public int nextInt() {
            int c;
            while ((c = next()) <= ' ') if (c == -1) throw new RuntimeException();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = next(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + c - '0';
                c = next();
            } while (c > ' ');
            return res * sgn;
        }
    }
}
